mapper.select:
select a.* from new_after_lease_check_external_query a
inner join client b on a.client_id = b.id

    
        and a.inspection_month = #{dto.inspectionMonth}
    
    
        and a.client_name like CONCAT('%',#{dto.clientName},'%')
    
    
        and a.sponsor_user_id = #{dto.sponsorUserId}
    
    
        and a.approval_status = #{dto.approvalStatus}

select count(1) from new_after_lease_check_external_query a
inner join client b on a.client_id = b.id

    
        and a.inspection_month = #{dto.inspectionMonth}
    
    
        and a.approval_status = #{dto.approvalStatus}
